// Captures every Synology Chat outgoing-webhook hit and writes the payload
// as a timestamped JSON file in /data/chatin (which is bind-mounted to
// /volume1/PoeTech/ChatIn on the Synology — SMB-accessible at
// \\192.168.1.26\PoeTech\ChatIn from any LAN client, no Drive Client needed).
// Path B — sovereign loop, no MCP, no external services.

const fs = require('fs');
const path = require('path');

const CHATIN_DIR = '/data/chatin';
fs.mkdirSync(CHATIN_DIR, { recursive: true });

// Webhook node may give us either the body or a wrapped { body, headers } shape
// depending on n8n version. Normalize both.
const input = $input.first().json || {};
const payload = input.body && typeof input.body === 'object' ? input.body : input;
const headers = $input.first().headers || input.headers || {};

// Synology Chat outgoing-webhook field names vary by DSM version. Synology
// historically sends user_name / user_id / channel_name / post_id / text in
// form-urlencoded form. Older docs and some third-party reverse-engineering
// reference 'username' instead. Try both and fall through cleanly.
function pick(obj, keys) {
  for (const k of keys) {
    if (obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
  }
  return null;
}

const senderRaw = pick(payload, ['user_name', 'username', 'userName', 'name']) || 'unknown';
const userId    = pick(payload, ['user_id', 'userId']);
const channel   = pick(payload, ['channel_name', 'channelName', 'channel']) || 'unknown-channel';
const channelId = pick(payload, ['channel_id', 'channelId']);
const postId    = pick(payload, ['post_id', 'postId', 'message_id']);
const text      = pick(payload, ['text', 'message', 'content']) || '';
const trigger   = pick(payload, ['trigger_word', 'triggerWord']);
const ts        = pick(payload, ['timestamp', 'created_at']);

const record = {
  captured_at: new Date().toISOString(),
  source: 'synology-chat-outgoing-webhook',
  normalized: {
    sender: senderRaw,
    user_id: userId,
    channel: channel,
    channel_id: channelId,
    post_id: postId,
    trigger_word: trigger,
    text: text,
    chat_timestamp: ts
  },
  headers,
  payload
};

const safeTs = record.captured_at.replace(/[:.]/g, '-');
const sender = String(senderRaw).replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 32);
const postIdFragment = (postId || '').toString().slice(0, 8);
const filename = path.join(
  CHATIN_DIR,
  `${safeTs}__${sender}${postIdFragment ? '__' + postIdFragment : ''}.json`
);

fs.writeFileSync(filename, JSON.stringify(record, null, 2));

// Family voice priority signal -- wake the Foundation Agent in real time.
// Per INPUT-VISIBILITY-TO-CLAUDE binding principle (2026-06-01): family-voice
// senders get an ntfy push so Claude / the operator sees them immediately
// rather than waiting for the 7am batch digest. Same topic as wf30 so all
// family voices land in one inbox regardless of source surface (Suggest button
// or Synology Chat).
const familyVoiceSenders = ['dpoe', 'cpoe', 'christiana', 'christian', 'christyn'];
const senderNormalized = String(senderRaw).toLowerCase().trim();
const isFamilyVoice = familyVoiceSenders.includes(senderNormalized);

if (isFamilyVoice) {
  const NTFY_BASE = 'http://ntfy:80';
  const NTFY_TOPIC = 'poetech-family-feedback';
  const preview = senderNormalized + ' [chat ' + channel + ']: ' + text.slice(0, 200);
  try {
    await fetch(NTFY_BASE + '/' + NTFY_TOPIC, {
      method: 'POST',
      headers: {
        'Title': 'PoeTech family voice (chat) - ' + senderNormalized,
        'Priority': '4',
        'Tags': 'speech_balloon',
        'Content-Type': 'text/plain'
      },
      body: preview,
      signal: AbortSignal.timeout(5000)
    });
  } catch (_) { /* ntfy down - captured locally either way */ }
}

return [{ json: { written: filename, text, sender, channel, captured_at: record.captured_at, isFamilyVoice } }];
